// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

// Enumerable also imports the base ERC721 contract
// if importing both, an override for _beforeTokenTransfer and supportsInterface was required
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
// Ownable allows you to add onlyOwner to functions
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/math/SafeMath.sol";

contract PFP is ERC721Enumerable, Ownable {
  using SafeMath for uint256;

  string private _baseTokenURI;
  string public PROVENANCE = "";
  uint256 public constant TOKEN_PRICE = 0.05 ether; // 0.05 ETH
  uint256 public constant MAX_TOKENS = 10000;
  uint256 public constant MAX_TOKENS_PER_PURCHASE = 5;
  bool public saleIsActive = false;

  // Used for withdrawals to various shareholders and wallets
  address[1] private _shareholders;
  uint[1] private _shares;
  event PaymentReleased(address to, uint256 amount);

  address[] public Admins;
  mapping(address => bool) public AdminByAddr;

  constructor() ERC721("Collectible", "CLTBL") {
    _shareholders[0] = 0x08DB61487a190701D6a847e24AF037906E8f832e; // adru
    // _shareholders[1] = 0x; // Giveaway wallet
    // _shareholders[2] = 0x; // Community wallet

    _shares[0] = 100;
    // _shares[1] = 0;
    // _shares[2] = 0;
  }

  modifier onlyAdmin() {
    require(AdminByAddr[_msgSender()] == true, "onlyAdmin");
    _;
  }

  function setAdmins(address[] memory _Admins) external onlyOwner {
    _setAdmins(_Admins);
  }

  function _setAdmins(address[] memory _Admins) internal {
    for (uint256 i = 0; i < Admins.length; i++) {
      AdminByAddr[Admins[i]] = false;
    }

    for (uint256 j = 0; j < _Admins.length; j++) {
      AdminByAddr[_Admins[j]] = true;
    }
    Admins = _Admins;
  }

  function getAdmins() external view returns (address[] memory) {
    return Admins;
  }

  function getOwners() public onlyAdmin view returns (address[] memory) {
    uint256 totalSupply = totalSupply();
    address[] memory ownerAddresses = new address[](totalSupply+1);
    for (uint i = 1; i <= totalSupply; i++) {
      ownerAddresses[i] = ERC721.ownerOf(i);
    }

    return ownerAddresses;
  }

  // Allows the owner to activate or deactivate the sale
  function flipSaleState() public onlyOwner {
    saleIsActive = !saleIsActive;
  }

  // Setting the baseURI allows you to replace the base url of the metadata in order to do a reveal
  function _baseURI() internal view virtual override returns (string memory) {
    return _baseTokenURI;
  }

  function setBaseURI(string memory baseURI) public onlyOwner {
    _baseTokenURI = baseURI;
  }

  // Provenance hash allows you and others to prove the uniqueness and origin of the NFT
  // The hash is based on the image itself so it does not work with items that are updated in the future
  function setProvenanceHash(string memory provenanceHash) public onlyOwner {
    PROVENANCE = provenanceHash;
  }

  // Reserve X amount of tokens for owner, team, other.
  function reserveTokens(address _to, uint256 _reserveAmount) public onlyOwner {
    require(totalSupply().add(_reserveAmount) <= MAX_TOKENS, "Exceeds maximum tokens available");

    for (uint i = 0; i < _reserveAmount; i++) {
      uint totalSupply = totalSupply();
      _safeMint(_to, totalSupply + 1);
    }
  }

  // Send ETH to an address
  function withdrawForGiveaway(uint256 amount, address payable to) public onlyOwner {
    uint256 balance = address(this).balance;
    require(balance > 0, "Insufficient balance");

    Address.sendValue(to, amount);
    emit PaymentReleased(to, amount);
  }

  // Withdraw the balance to the shareholders
  function withdrawAll() public onlyOwner {
    uint256 balance = address(this).balance;
    require(balance > 0, "Insufficient balance");

    for (uint256 i = 0; i < 1; i++) {
      uint256 payment = balance.mul(_shares[i]).div(100);

      Address.sendValue(payable(_shareholders[i]), payment);
      emit PaymentReleased(_shareholders[i], payment);
    }
  }

  // Public mint!
  function mintCollectible(uint256 _count) public payable {
    require(totalSupply() <= MAX_TOKENS, "Maximum tokens minted. The sale is over.");
    require(saleIsActive, "Sale is not active, so you cannot mint.");
    require(_count > 0 && _count < MAX_TOKENS_PER_PURCHASE + 1, "Exceeds maximum tokens you can purchase in a single transaction");
    require(totalSupply().add(_count) <= MAX_TOKENS, "Exceeds maximum tokens available for purchase");
    require(msg.value == TOKEN_PRICE.mul(_count), "Value sent is not correct");

    for(uint256 i = 0; i < _count; i++){
      uint256 totalSupply = totalSupply();
      if (totalSupply < MAX_TOKENS) {
        _safeMint(msg.sender, totalSupply + 1);
      } else if (totalSupply == MAX_TOKENS) {
        saleIsActive = false;
      }
    }
  }
}
